        contains('from-the-future'),
      );
    });

    test('AC1 pair guard: persisted chatgpt-codex over a stale foreign '
        'baseUrl degrades with a named warning, never bricks', () async {
      // The realistic partial write: a surface overwrites provider: on an
      // existing config and keeps its baseUrl (the CLI's persisted default,
      // openrouter). The codex kind speaks the OAuth Codex wire on
      // chatgpt.com ONLY, so the PAIR is unservable — the boot must say
      // exactly that and complete the turn on the fallback (gh-760 review:
      // the previous shape died at the key gate with guidance that named
      // CHATGPT_OAUTH_CREDENTIALS as missing while it was set).
      writeConfig('''
provider: chatgpt-codex
model: mock-model
baseUrl: ${server.baseUrl}
mode: code
approvalMode: yolo
''');

      final result = await runFa(
        'say something',
        extraEnv: const {'CHATGPT_OAUTH_CREDENTIALS': 'dummy-creds'},
      );

      expect(result.exitCode, 0, reason: result.output);
      expect(
        result.stderr,
        contains(
          'saved provider "chatgpt-codex" only works with its own '
          'default endpoint',
        ),
        reason: result.output,
      );
      expect(result.stderr, contains('is not servable by it'));
      // The key-gate lie is gone: the env creds were never the problem.
      expect(result.stderr, isNot(contains('missing API key')));
      expect(result.stderr, isNot(contains('unknown provider')));
      expect(
        File('${tempHome.path}/.fah/crash.log').existsSync(),
        isFalse,
        reason: result.output,
      );
      // The turn completed on the FALLBACK provider (the mock endpoint).
      expect(result.stdout, contains('fallback reply'));
      // Nothing was silently rewritten (warn, don't mutate).
      expect(
        File('${tempHome.path}/.fah/config.yaml').readAsStringSync(),
        contains('chatgpt-codex'),
      );
    });

    test('E3: a roles chain on the unknown provider degrades to the '
        'legacy model instead of failing the boot', () async {
      writeConfig('''
provider: openai-completions
model: mock-model
baseUrl: ${server.baseUrl}
mode: code
approvalMode: yolo
roles:
  default:
    - provider: from-the-future
      model: future-model
''');

      final result = await runFa('say something');

      expect(result.exitCode, 0, reason: result.output);
      expect(
        result.stderr,
        contains('model roles config is unusable'),
        reason: result.output,
      );
      expect(result.stderr, contains('unknown provider'));
      expect(result.stdout, contains('fallback reply'));
    });

    test('BLOCKING regression: a persisted catalog NAME (provider: openai) '
        'boots and completes a turn on its adapter kind', () async {
      // gh-760 review blocker: the raw saved NAME reaching
      // providerStreamFunction bricked the boot with
      // `ConfigException: Unknown provider kind: openai` + crash.log.
      // The restore must land on the resolved spec's KIND.
      writeConfig('''
provider: openai
model: mock-model
baseUrl: ${server.baseUrl}
mode: code
approvalMode: yolo
''');

      final result = await runFa('say something');

      expect(result.exitCode, 0, reason: result.output);
      expect(result.output, isNot(contains('Unknown provider kind')));
      expect(
        File('${tempHome.path}/.fah/crash.log').existsSync(),
        isFalse,
        reason: result.output,
      );
      // The turn completed on the resolved kind (openai-completions) via
      // the mock endpoint.
      expect(result.stdout, contains('fallback reply'));
    });

    test('BLOCKING regression: the name form of the ticket provider '
        '(provider: chatgpt) no longer bricks the boot', () async {
      // Same pair guard as the kind form: the name resolves to the
      // endpoint-locked codex kind, the stale foreign baseUrl degrades
      // with the named warning, the turn completes on the fallback.
      writeConfig('''
provider: chatgpt
model: mock-model
baseUrl: ${server.baseUrl}
mode: code
approvalMode: yolo
''');

      final result = await runFa(
        'say something',
        extraEnv: const {'CHATGPT_OAUTH_CREDENTIALS': 'dummy-creds'},
      );

      expect(result.exitCode, 0, reason: result.output);
      expect(result.output, isNot(contains('Unknown provider kind')));
      expect(
        File('${tempHome.path}/.fah/crash.log').existsSync(),
        isFalse,
        reason: result.output,
      );
      expect(
        result.stderr,
        // #772 canonicalizes the saved NAME at load (`chatgpt` ->
        // `chatgpt-codex`), so the pair guard reports the persisted KIND;
        // the load note above names the name->kind mapping.
        contains(
          'saved provider "chatgpt-codex" only works with its own '
          'default endpoint',
        ),
        reason: result.output,
      );
      expect(result.stdout, contains('fallback reply'));
    });

    test('folder model state carrying a catalog NAME normalizes to the '
        'adapter kind instead of bricking the boot', () async {
      // The state file is CLI-written with kinds, but it lives in the
      // same shared-config family — a name-carrying file must normalize
      // (or be ignored with a warning), never leak the raw name into the
      // stream factory.
      writeConfig('''
provider: openai-completions
model: mock-model
baseUrl: ${server.baseUrl}
mode: code

    final upper = key.toUpperCase();
    return key.startsWith('FA_') ||
        upper.endsWith('_API_KEY') ||
        upper.endsWith('_TOKEN') ||
        upper.endsWith('_SECRET') ||
        upper.endsWith('_KEY') ||
        upper.endsWith('_CREDENTIALS');
  }

  return Map<String, String>.of(Platform.environment)
    ..removeWhere((key, _) => ambient(key));
}

/// The one spawn site both IT families share (`runFaHeadless` here,
/// `runFaHeadlessRaw` below): the scrubbed
/// environment, the credential blank-pins and the `dart run bin/fah.dart`
/// invocation live HERE so the two families cannot diverge on what
/// "scrubbed" means (gh-760 review). [fahArgs] carries everything after
/// the script path; [env] and [extraEnv] layer over the scrub in that
/// order.
Future<FaResult> spawnFa({
  required List<String> fahArgs,
  Map<String, String> env = const {},
  Map<String, String> extraEnv = const {},
  Duration timeout = const Duration(minutes: 2),
}) async {
  // Scrub the ambient FA_* environment (a developer/CI shell may export
  // FA_PROVIDER_*/FA_PROVIDERS_QUEUE/FA_LOG_FILE/...): those are
  // boot-resolution inputs. Blank values read as unset at every consumer,
  // so the explicit blanks keep the override minimal where the injection
  // re-adds missing vars.
  // gh-1300: honor the FA_BIN AOT seam — CI compiles the bundle ONCE per
  // shard and every headless spawn here drops from ~30 s (VM+CFE) to ~1 s.
  final command = faCliCommand(
    fahArgs,
    jitPrefix: const ['dart', 'run', 'bin/fah.dart'],
  );
  final result = await Process.run(
    command.first,
    command.sublist(1),
    workingDirectory: Directory.current.path,
    environment: {
      ...scrubbedChildEnv(),
      'OPENAI_API_KEY': 'mock',
      'FA_PROVIDER_TYPE': '',
      'FA_PROVIDER_NAME': '',
      'FA_PROVIDER_CONFIG': '',
      'FA_PROVIDER_CONFIG_BASE64': '',
      'FA_PROVIDERS_QUEUE': '',
      'FA_LOG_FILE': '',
      ...env,
      ...extraEnv,
    },
    stdoutEncoding: utf8,
    stderrEncoding: utf8,
  ).timeout(timeout);
  return FaResult(
    stdout: result.stdout as String,
    stderr: result.stderr as String,
    exitCode: result.exitCode,
  );
}

/// Runs one headless prompt against the CLI.
///
/// [workspace] is passed as `--cwd` (cube manifests, cache and session cwd
/// resolve there); [env] entries are layered over the inherited environment
/// (pass `HOME` pointing at a temp home so the CLI never reads the
/// developer's real `~/.fah`). `OPENAI_API_KEY` is pinned to `mock` unless
/// overridden. Throws [TimeoutException] past [timeout].
Future<FaResult> runFaHeadless({
  required Directory workspace,
  required String baseUrl,
  required String prompt,
  String? cube,
  String? cubeConfig,
  Map<String, String> env = const {},
  Duration timeout = const Duration(minutes: 2),
}) {
  return spawnFa(
    fahArgs: [
      '--provider',
      'openai-completions',
      '--base-url',
      baseUrl,
      '--model',
      'mock-model',
      '--cwd',
      workspace.path,
      if (cube != null) ...['--cube', cube],
      if (cubeConfig != null) ...['--cube-config', cubeConfig],
      '-p',
      prompt,
    ],
    env: env,
    timeout: timeout,
  );
}

/// [runFaHeadless] without the explicit `--provider/--base-url/--model`
/// flags: the boot must resolve everything from the on-disk config (e.g.
/// gh-760's poisoned-config fixtures and gh-1199's live-wire boot leg).
/// Lives in the shared helper so every config-resolution family drives
/// the exact same spawn (gh-760: the scrub + blank pins are the test).
Future<FaResult> runFaHeadlessRaw({
  required Directory workspace,
  required String prompt,
  Map<String, String> env = const {},
  Map<String, String> extraEnv = const {},
  Duration timeout = const Duration(minutes: 2),
}) {
  // The shared [spawnFa] owns the scrub + blank pins (see its doc): the
  // boot must resolve ONLY from the config fixture — an inherited
  // FA_PROVIDER_* declaration would legitimately override it and defeat
  // the test.
  return spawnFa(
    fahArgs: ['--cwd', workspace.path, '-p', prompt],
    env: env,
    extraEnv: extraEnv,
    timeout: timeout,
  );
}

