        workspace: workspace,
        prompt: prompt,
        env: {'HOME': tempHome.path},
        extraEnv: extraEnv,
      );
    }

    test('IT-B2/AC2: an unknown persisted provider id boots on the '
        'fallback with a named warning', () async {

