      File('${tempHome.path}/.fah/config.yaml')
        ..createSync(recursive: true)
        ..writeAsStringSync(body);
    }

    Future<FaResult> runFa(
      String prompt, {
      Map<String, String> extraEnv = const {},
    }) {
      return runFaHeadlessRaw(
        workspace: workspace,
