/// The one spawn site both IT families share (`runFaHeadless` here,
/// `runFaHeadlessRaw` below): the scrubbed
/// environment, the credential blank-pins and the `dart run bin/fah.dart`
/// invocation live HERE so the two families cannot diverge on what
/// "scrubbed" means (gh-760 review). [fahArgs] carries everything after
/// the script path; [env] and [extraEnv] layer over the scrub in that
/// order.
Future<FaResult> spawnFa({
  required List<String> fahArgs,
  Map<String, String> env = const {},
  Map<String, String> extraEnv = const {},
  Duration timeout = const Duration(minutes: 2),
}) async {
  // Scrub the ambient FA_* environment (a developer/CI shell may export
  // FA_PROVIDER_*/FA_PROVIDERS_QUEUE/FA_LOG_FILE/...): those are
  // boot-resolution inputs. Blank values read as unset at every consumer,
  // so the explicit blanks keep the override minimal where the injection
  // re-adds missing vars.
  // gh-1300: honor the FA_BIN AOT seam — CI compiles the bundle ONCE per
  // shard and every headless spawn here drops from ~30 s (VM+CFE) to ~1 s.
  final command = faCliCommand(
    fahArgs,
    jitPrefix: const ['dart', 'run', 'bin/fah.dart'],
  );
  final result = await Process.run(
    command.first,
    command.sublist(1),
    workingDirectory: Directory.current.path,
    environment: {
      ...scrubbedChildEnv(),
      'OPENAI_API_KEY': 'mock',
      'FA_PROVIDER_TYPE': '',
      'FA_PROVIDER_NAME': '',
      'FA_PROVIDER_CONFIG': '',
      'FA_PROVIDER_CONFIG_BASE64': '',
      'FA_PROVIDERS_QUEUE': '',
      'FA_LOG_FILE': '',
      ...env,
      ...extraEnv,
    },
    stdoutEncoding: utf8,
    stderrEncoding: utf8,
  ).timeout(timeout);
  return FaResult(
    stdout: result.stdout as String,
    stderr: result.stderr as String,
    exitCode: result.exitCode,
  );
}

/// Runs one headless prompt against the CLI.
///
/// [workspace] is passed as `--cwd` (cube manifests, cache and session cwd
/// resolve there); [env] entries are layered over the inherited environment
/// (pass `HOME` pointing at a temp home so the CLI never reads the
/// developer's real `~/.fah`). `OPENAI_API_KEY` is pinned to `mock` unless
/// overridden. Throws [TimeoutException] past [timeout].
Future<FaResult> runFaHeadless({
  required Directory workspace,
  required String baseUrl,
  required String prompt,
  String? cube,
  String? cubeConfig,
  Map<String, String> env = const {},
  Duration timeout = const Duration(minutes: 2),
}) {
  return spawnFa(
    fahArgs: [
      '--provider',
      'openai-completions',
      '--base-url',
      baseUrl,
      '--model',
      'mock-model',
      '--cwd',
      workspace.path,
      if (cube != null) ...['--cube', cube],
      if (cubeConfig != null) ...['--cube-config', cubeConfig],
      '-p',
      prompt,
    ],
    env: env,
    timeout: timeout,
  );
}

/// [runFaHeadless] without the explicit `--provider/--base-url/--model`
/// flags: the boot must resolve everything from the on-disk config (e.g.
/// gh-760's poisoned-config fixtures and gh-1199's live-wire boot leg).
/// Lives in the shared helper so every config-resolution family drives
/// the exact same spawn (gh-760: the scrub + blank pins are the test).
Future<FaResult> runFaHeadlessRaw({
  required Directory workspace,
  required String prompt,
  Map<String, String> env = const {},
  Map<String, String> extraEnv = const {},
  Duration timeout = const Duration(minutes: 2),
}) {
  // The shared [spawnFa] owns the scrub + blank pins (see its doc): the
  // boot must resolve ONLY from the config fixture — an inherited
  // FA_PROVIDER_* declaration would legitimately override it and defeat
  // the test.
  return spawnFa(
    fahArgs: ['--cwd', workspace.path, '-p', prompt],
    env: env,
    extraEnv: extraEnv,
    timeout: timeout,
  );
}

